INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Implantatbehandlung',
'<p>Wenn ein Zahn verloren geht, bleibt die entstandene Lücke nicht unverändert. Die Nachbarzähne können mit der Zeit in die Lücke kippen, der Zahn im Gegenkiefer kann sich verlängern, und die Kaubelastung verteilt sich ungleichmäßig auf die verbliebenen Zähne. Auch der Kieferknochen in diesem Bereich kann an Volumen verlieren, weil die Belastung, die er zuvor getragen hat, entfällt. Der Ersatz eines fehlenden Zahnes ist deshalb häufig keine reine Frage des Aussehens.</p>
<p>Ein Zahnimplantat ist eine künstliche Zahnwurzel, die anstelle des fehlenden Zahnes in den Kieferknochen eingesetzt wird. Darauf kann eine Einzelkrone, eine Brücke für mehrere Zähne oder eine festsitzende Versorgung für den gesamten Kiefer angefertigt werden. Die Aufgabe des Implantats besteht darin, die verlorene Wurzel zu ersetzen und den Zahnersatz vom Knochen aus zu tragen.</p>
<h2>Nicht jede Zahnlücke wird mit einem Implantat versorgt</h2>
<p>Ein Implantat ist nicht die einzige Möglichkeit, einen fehlenden Zahn zu ersetzen. Auch eine zahngetragene Brücke, eine herausnehmbare Teilprothese und in manchen Fällen ein kieferorthopädischer Lückenschluss kommen in Betracht. Welche Option geeignet ist, ergibt sich aus der gemeinsamen Beurteilung von Lage und Größe der Lücke, dem Zustand der Nachbarzähne, Volumen und Qualität des Kieferknochens, der Zahnfleischgesundheit, dem Bissverhältnis, dem Allgemeinzustand und den täglichen Pflegegewohnheiten.</p>
<p>Diese Beurteilung erfolgt durch Untersuchung, die erforderliche Bildgebung und die prothetische Planung. Eine verbindliche Aussage zur Eignung, die telefonisch, per Nachricht oder anhand eines Fotos getroffen wird, ist nicht verlässlich.</p>
<h2>Die Behandlung ist ein Ablauf, kein einzelner Eingriff</h2>
<p>Die Implantatbehandlung besteht im Allgemeinen aus folgenden Schritten: Untersuchung und Bildgebung, Erstellung des Behandlungsplans, erforderliche Vorbehandlungen, Einsetzen des Implantats, die Einheilphase, in der das Implantat mit dem Knochen verwächst, Anfertigung der Versorgung und regelmäßige Kontrollen.</p>
<p>Die Dauer dieser Schritte ist von Person zu Person deutlich verschieden. Ein Fall mit ausreichendem Knochenangebot verläuft nicht nach demselben Zeitplan wie ein Fall, der einen Knochenaufbau erfordert. Deshalb wird keine feste Dauer zugesagt; die voraussichtlichen Schritte werden nach der Untersuchung mitgeteilt.</p>
<h2>Das Langzeitergebnis hängt nicht von einem einzigen Faktor ab</h2>
<p>Ob ein Implantat viele Jahre seine Funktion erfüllt, hängt von der richtigen Fallauswahl, der Planung, der chirurgischen und prothetischen Umsetzung, der Mundhygiene, dem Rauchverhalten, dem Allgemeinzustand und regelmäßigen Kontrollen ab. Wird einer dieser Faktoren übersehen, kann das Ergebnis beeinträchtigt werden. Das Gewebe um ein Implantat kann sich ebenso entzünden wie bei natürlichen Zähnen; mit dem Ende der Behandlung endet die Pflege also nicht.</p>
<h2>Was wird vor einem Implantat beurteilt?</h2>
<p>Bei der Untersuchung wird nicht nur der Bereich der Lücke betrachtet. Der Zustand der verbliebenen Zähne, die Zahnfleischgesundheit, das Bissverhältnis und ein etwaiges Pressen oder Knirschen werden beurteilt. Besteht eine Zahnfleischerkrankung, wird sie vor dem Implantat behandelt, denn das Gewebe um ein Implantat ist von derselben bakteriellen Plaque betroffen.</p>
<p>Auch die Krankengeschichte gehört zur Planung. Ein nicht eingestellter Diabetes, bestimmte Medikamente mit Einfluss auf den Knochenstoffwechsel, Gerinnungsstörungen, eine vorangegangene Strahlentherapie und Rauchen sind Faktoren, die die Heilung beeinflussen können. Keiner davon ist für sich genommen ein absolutes Hindernis, doch sie können die Planung und den erwarteten Verlauf verändern. Deshalb ist es wichtig, uns beim ersten Gespräch über Ihre Medikamente und bekannten Erkrankungen zu informieren.</p>
<h2>Der Zahnersatz wird nicht erst nach dem Implantat geplant</h2>
<p>Ein verbreitetes Missverständnis lautet, das Implantat werde zuerst gesetzt und der darauf sitzende Zahn danach geplant. Tatsächlich ist die Reihenfolge umgekehrt: Zuerst wird festgelegt, welcher Zahn in welcher Form und an welcher Stelle entstehen soll; Position und Achse des Implantats richten sich nach diesem Plan. Man spricht von prothetisch orientierter Planung.</p>
<p>Praktisch bedeutet das: Auf einem nicht korrekt positionierten Implantat lässt sich unter Umständen kein gut geformter, reinigungsfähiger und ästhetischer Zahn anfertigen, selbst wenn es einwandfrei mit dem Knochen verwächst. Die Planungsphase ist daher nicht weniger wichtig als der chirurgische Eingriff.</p>
<h2>Seiten in diesem Bereich</h2>
<h3>Am Anfang der Implantatbehandlung</h3>
<ul>
<li><a href="/de/dental-implant-tedavisi/">Zahnimplantat-Behandlung</a> — Aufgabe des Implantats, für wen es in Betracht kommt, die Behandlungsschritte und die Einheilung.</li>
<li>Möglichkeiten beim Ersatz fehlender Zähne — Unterschiede zwischen Implantat, Brücke und herausnehmbarem Zahnersatz. <em>(in Vorbereitung)</em></li>
<li>Implantat-Behandlungsplan und Umfang — Was den Behandlungsplan bestimmt. <em>(in Vorbereitung)</em></li>
<li>Wann kann nach einer Zahnentfernung implantiert werden? — Die Kriterien für den Zeitpunkt. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Wenn der Knochen nicht ausreicht</h3>
<ul>
<li>Knochentransplantat und Knochenaufbau — Verfahren bei unzureichendem Knochenangebot. <em>(in Vorbereitung)</em></li>
<li>Sinuslift — Das Vorgehen bei geringer Knochenhöhe im hinteren Oberkiefer. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Versorgung und Zahnersatz</h3>
<ul>
<li>Festsitzender implantatgetragener Zahnersatz — Einzelkronen, Brücken und festsitzende Versorgungen für den ganzen Kiefer. <em>(in Vorbereitung)</em></li>
<li>All-on-4 und All-on-6 — Festsitzender Zahnersatz auf einer begrenzten Zahl von Implantaten. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Eingriff und Heilung</h3>
<ul>
<li>Ist eine Implantatbehandlung schmerzhaft? — Lokalanästhesie und Heilungsphase. <em>(in Vorbereitung)</em></li>
<li>Die ersten Tage nach dem Implantat — Schmerzen, Schwellung, Blutung, Ernährung und Pflege. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Langfristige Pflege</h3>
<ul>
<li>Wie werden Implantate gereinigt? — Die tägliche Reinigungsroutine und Interdentalbürsten. <em>(in Vorbereitung)</em></li>
<li>Implantate bei Rauchern und Diabetes — Wie sich diese beiden Faktoren auf die Heilung auswirken. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Wenn Probleme auftreten</h3>
<ul>
<li>Warum gehen Implantate verloren? — Ursachen für frühen und späten Implantatverlust. <em>(in Vorbereitung)</em></li>
<li>Periimplantitis — Entzündung und Knochenabbau um ein Implantat. <em>(in Vorbereitung)</em></li>
</ul>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Sind Implantate bei jedem möglich?</strong><br>Die Eignung ergibt sich aus der gemeinsamen Beurteilung von Volumen und Qualität des Kieferknochens, der Zahnfleischgesundheit, dem Allgemeinzustand, den eingenommenen Medikamenten, dem Rauchverhalten und der Mundhygiene. Ohne Untersuchung und Bildgebung kann keine Entscheidung getroffen werden.</p>
<p><strong>Womit fange ich an?</strong><br>Der erste Schritt ist die Untersuchung. Nachdem Ihr Anliegen, die Befunde in der Mundhöhle und die erforderliche Bildgebung gemeinsam beurteilt wurden, werden Ihnen die Optionen und die voraussichtlichen Schritte mitgeteilt.</p>
<p><strong>Wie viele Implantate brauche ich?</strong><br>Die Zahl der fehlenden Zähne ist nicht allein ausschlaggebend. Knochenverteilung, Kaubelastung, die geplante Art des Zahnersatzes und ästhetische Erfordernisse werden gemeinsam beurteilt. Vor der Untersuchung wird keine Anzahl zugesagt.</p>
<p><strong>Ist nach einem Implantat besondere Pflege nötig?</strong><br>Ja. Das Gewebe um ein Implantat kann sich entzünden. Tägliche Reinigung, Interdentalpflege und regelmäßige Kontrollen wirken sich unmittelbar auf das Langzeitergebnis aus.</p>
<p><strong>Ist mein Alter ein Hindernis für Implantate?</strong><br>Eine Altersobergrenze gibt es nicht; entscheidend ist nicht das Alter, sondern der Knochen- und Zahnfleischhalt sowie der Allgemeinzustand. Nach unten wird vorausgesetzt, dass das Kieferwachstum abgeschlossen ist.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt wird die Eignung für Implantate durch die gemeinsame Beurteilung von klinischer Untersuchung, erforderlichen Röntgenbefunden und prothetischer Planung bestimmt. Im Anschluss werden Ihnen die Optionen und die voraussichtlichen Schritte schriftlich mitgeteilt.</p>
<p><a href="/de/agiz-cerrahisi-uygulamalari/">Oralchirurgische Eingriffe</a> &middot; <a href="/de/iletisim">Termin und Kontakt</a></p>',
'Was ist eine Implantatbehandlung, für wen kommt sie infrage und aus welchen Schritten besteht sie? Planung, Chirurgie, Zahnersatz und Nachsorge.',
'Implantatbehandlung | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'implant';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Ästhetische Zahnheilkunde',
'<p>Die ästhetische Zahnheilkunde hat zum Ziel, Farbe, Form und Stellung der Zähne mit dem Gesicht in Einklang zu bringen. Die Grundlage dieser Arbeit ist jedoch immer die Mundgesundheit. Bestehen aktive Karies, eine Zahnfleischentzündung, ein unbehandeltes Wurzelproblem oder ein gestörter Biss, wird darauf kein ästhetischer Eingriff aufgebaut; diese Probleme werden zuerst behandelt.</p>
<p>Der Grund dafür ist nicht allein eine Regel. Der Rand einer Restauration, die an entzündetes Zahnfleisch gesetzt wird, kann mit der Zeit frei liegen, und wird eine Pressgewohnheit übersehen, kann neu eingesetzte Keramik früher als erwartet Schaden nehmen. Deshalb beginnt die ästhetische Planung mit einer Untersuchung.</p>
<h2>Eine einzige Methode passt nicht für alle</h2>
<p>Zwei Menschen mit demselben Anliegen erhalten nicht zwangsläufig dieselbe Behandlung. Bei einem dunkler gewordenen Zahn genügt manchmal eine Aufhellung, manchmal liegt eine Ursache zugrunde und es ist eine restaurative Lösung erforderlich. Bei einer kleinen Formunregelmäßigkeit reicht Bonding, bei ausgedehntem Substanzverlust kommt eine Krone in Betracht. Bei Stellungsproblemen kann eine kieferorthopädische Beurteilung schonender sein als ein restaurativer Eingriff.</p>
<p>Bei der Entscheidung werden gemeinsam beurteilt: die verbliebene gesunde Zahnsubstanz, die Schmelzmenge, die Position des Zahns im Mund, die Grundfarbe, die Zahnfleischverläufe, die Kaukraft, ein etwaiges Pressen oder Knirschen und die Erwartung der Patientin oder des Patienten. Ziel ist es, das Ergebnis auf dem schonendsten möglichen Weg zu erreichen.</p>
<h2>Wie wird ein natürliches Aussehen geplant?</h2>
<p>Ein natürliches Ergebnis entsteht aus dem Zusammenspiel des Ganzen, nicht aus einzelnen Zähnen. Zahnproportionen, Oberflächenstruktur, Lichtdurchlässigkeit, der Verlauf des Zahnfleischrandes, die Lachlinie und das Verhältnis von Lippen und Zähnen werden gemeinsam betrachtet. Zähne nur aufzuhellen oder alle in derselben Größe anzufertigen ergibt kein natürliches Bild; entscheidend ist das Verhältnis zu den Nachbarzähnen und zum Gesicht.</p>
<p>Auch das Zahnfleisch gehört zu diesem Ganzen. Wie viel Zahnfleisch beim Lächeln sichtbar wird, die Symmetrie der Verläufe und die Gesundheit des Gewebes wirken sich auf den natürlichen Eindruck ebenso aus wie die Zähne.</p>
<h2>Erwartungen und Grenzen werden offen besprochen</h2>
<p>Einer der wichtigsten Schritte in der ästhetischen Behandlung ist, die Erwartungen vor Beginn zu besprechen. In geeigneten Fällen lässt sich mit digitaler Planung und einer Vorschau eine Vorstellung vom möglichen Ergebnis gewinnen. Eine Vorschau ist ein Planungsmittel; sie ist keine Zusage eines identischen Ergebnisses.</p>
<p>Keramik und Komposit verhalten sich farblich anders als natürliche Zähne: Ein natürlicher Zahn verändert sich mit der Zeit, während eine Restauration gleich bleiben kann. Werden Aufhellung und restaurative Arbeit zusammen geplant, ist deshalb die Reihenfolge wichtig. Ebenso lässt sich für keine Restauration eine feste Nutzungsdauer angeben; das Ergebnis wird ebenso von Pflege, Biss und Kontrollen bestimmt wie von der Materialwahl.</p>
<h2>Die Reihenfolge verändert das Ergebnis</h2>
<p>In der ästhetischen Behandlung ist die Reihenfolge der Eingriffe ebenso wichtig wie die Eingriffe selbst. Der allgemeine Ansatz lautet: Zuerst werden Probleme der Mundgesundheit gelöst, danach wird bei Bedarf die Zahnstellung korrigiert, anschließend die Farbe bearbeitet und zuletzt werden die restaurativen Arbeiten abgeschlossen.</p>
<p>Der Grund dafür ist praktischer Natur. Sollen die Zähne kieferorthopädisch korrigiert werden, passen vorher eingesetzte Kronen möglicherweise nicht zur neuen Position. Ist eine Aufhellung geplant, sollten Restaurationen im sichtbaren Bereich nach dem erreichten Farbton ausgewählt werden, denn Keramik und Komposit werden durch eine Aufhellung nicht verändert.</p>
<h2>Wann ist weniger besser?</h2>
<p>In der ästhetischen Zahnheilkunde entsteht das beste Ergebnis nicht immer aus dem umfangreichsten Eingriff. Einmal entfernter gesunder Schmelz wächst nicht nach; lässt sich dasselbe Ergebnis auf schonenderem Weg erreichen, wird dieser Weg bevorzugt.</p>
<p>Beispiele: Bei einer kleinen Fraktur an einem einzelnen Zahn kann statt einer Krone Bonding infrage kommen; bei einer leichten Verfärbung kann eine Aufhellung statt einer Restauration genügen; eine Lücke zwischen den Zähnen lässt sich in manchen Fällen kieferorthopädisch schließen. Nicht jede dieser Optionen ist in jedem Fall geeignet, doch sie sollten bei der Untersuchung gemeinsam beurteilt werden. Wird Ihnen nur eine einzige Option angeboten, haben Sie das Recht zu fragen, warum die Alternativen nicht geeignet sind.</p>
<h2>Seiten in diesem Bereich</h2>
<h3>Planung</h3>
<ul>
<li><a href="/de/gulus-tasarimi/">Individuelles Smile Design</a> — Der Planungsprozess, in dem Zähne, Zahnfleisch, Lippen und Gesichtsproportionen gemeinsam beurteilt werden.</li>
<li>Proportionen im Smile Design — Wo Proportionsregeln nützlich sind. <em>(in Vorbereitung)</em></li>
<li>Rote Ästhetik und Zahnfleischkorrektur — Zahnfleischverläufe und Symmetrie. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Kronen und Veneers</h3>
<ul>
<li><a href="/de/zirkonyum-dis-kaplama/">Zirkonkronen</a> — Einsatzgebiete, digitaler Arbeitsablauf, Materialoptionen und Pflege.</li>
<li>E.max und Veneers — Eignung für Lithiumdisilikat- und Veneerversorgungen. <em>(in Vorbereitung)</em></li>
<li>Veneer oder Zirkon? — Ein Vergleich der beiden Optionen. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Schonendere Optionen</h3>
<ul>
<li>Bonding und ästhetische Kompositfüllungen — Ein schonender Ansatz für begrenzte Form- und Farbkorrekturen. <em>(in Vorbereitung)</em></li>
<li><a href="/de/dis-beyazlatma/">Zahnaufhellung</a> — Verfahren in der Praxis, zu Hause und in Kombination; Umgang mit Empfindlichkeit.</li>
</ul>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Womit fange ich an, welche Behandlung brauche ich?</strong><br>Ausgangspunkt ist eine Smile-Design-Beurteilung. Nachdem Ihre Erwartungen, die Befunde zur Mundgesundheit und der Biss gemeinsam untersucht wurden, erläutern wir, welche Eingriffe geeignet sind und ob es eine schonendere Alternative gibt.</p>
<p><strong>Müssen meine Zähne beschliffen werden?</strong><br>Nein. In manchen Fällen genügen Optionen ohne Beschleifen, etwa eine Aufhellung oder Bonding. Der Umfang der Präparation hängt vom vorhandenen Zustand des Zahns und der gewählten Restauration ab.</p>
<p><strong>Erst aufhellen oder erst Kronen?</strong><br>Sollen die natürlichen Zähne aufgehellt werden, werden Restaurationen im sichtbaren Bereich üblicherweise danach und passend zum erreichten Farbton angefertigt. Restaurative Materialien verändern ihre Farbe nicht wie natürliche Zähne.</p>
<p><strong>Wie lange hält das Ergebnis?</strong><br>Eine feste Dauer lässt sich nicht angeben. Materialwahl, verbliebene Substanz, Kaubelastung, Pressen oder Knirschen, Mundhygiene und regelmäßige Kontrollen beeinflussen das Ergebnis.</p>
<p><strong>Ich knirsche mit den Zähnen — ist ein ästhetischer Eingriff möglich?</strong><br>Pressen und Knirschen beeinflussen die Planung und werden zuerst beurteilt. Bei Bedarf wird eine schützende Nachtschiene Teil des Plans.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt werden die Optionen der ästhetischen Behandlung gemeinsam mit Mundgesundheit, Erhalt der Zahnsubstanz, Bissverhältnis und dem Ziel eines natürlichen Aussehens beurteilt.</p>
<p><a href="/de/iletisim">Termin und Kontakt</a></p>',
'Smile Design, Zirkon, Veneers, Bonding und Aufhellung: welche Option wann infrage kommt und warum die Reihenfolge wichtig ist.',
'Ästhetische Zahnheilkunde | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'estetik';


INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Mund- und Zahngesundheit',
'<p>Meist wartet man auf Schmerzen, bevor man zum Zahnarzt geht. Dabei sind Schmerzen in vielen Fällen nicht der Anfang, sondern ein fortgeschrittenes Stadium. Karies tut nicht weh, solange sie auf den Schmelz beschränkt ist; die Gingivitis, das frühe Stadium der Zahnfleischerkrankung, zeigt außer einer Blutung oft kein Anzeichen. Regelmäßige Kontrollen ermöglichen es daher, eine Behandlung mit einem kleineren Eingriff und weniger Substanzverlust abzuschließen.</p>
<p>Dieser Bereich behandelt die Stellen, an denen Mund- und Zahngesundheit den Alltag berühren: Karies und Füllungen, Zahnfleischprobleme, Schmerzen und Notfälle, Empfindlichkeit, Kiefer- und Muskelbeschwerden, tägliche Pflegegewohnheiten und die Zahngesundheit von Kindern.</p>
<h2>Der Mund ist vom übrigen Körper nicht getrennt</h2>
<p>Der Zusammenhang zwischen Zahnfleischerkrankung und Diabetes wirkt in beide Richtungen: Ein nicht eingestellter Blutzucker kann das Zahnfleischgewebe beeinträchtigen, während eine anhaltende Zahnfleischentzündung die Blutzuckereinstellung erschweren kann. Ebenso können hormonelle Veränderungen in der Schwangerschaft das Zahnfleisch empfindlicher gegenüber Plaque machen. Manche Medikamente führen zu Mundtrockenheit und können dadurch das Kariesrisiko erhöhen.</p>
<p>Deshalb betrachtet eine Untersuchung nicht nur die Zähne. Krankengeschichte, eingenommene Medikamente und bestehende Allgemeinerkrankungen gehören zur Planung. Bei Bedarf stimmen wir uns mit der behandelnden Ärztin oder dem behandelnden Arzt ab.</p>
<h2>Tägliche Pflege ist die Fortsetzung der Behandlung</h2>
<p>Kein Eingriff in der Praxis ersetzt die Pflege zu Hause. Sammelt sich nach einer professionellen Zahnreinigung weiter Plaque an, kehrt die Zahnfleischentzündung zurück; wird in einem versorgten Gebiss das Kariesrisiko nicht gesteuert, entsteht neue Karies. Putztechnik, Interdentalreinigung, die Wahl der Zahnpasta und die Ernährung sind daher ebenso wichtig wie die Behandlung selbst.</p>
<p>Das richtige Hilfsmittel ist nicht für alle dasselbe. Die Breite der Zahnzwischenräume, vorhandener Zahnersatz oder Implantate, die Geschicklichkeit der Hände und die Gewohnheiten können unterschiedliche Hilfsmittel erfordern.</p>
<h2>Bei Schmerzen und Notfällen ist Abwarten schädlich</h2>
<p>Starke Zahnschmerzen, eine Schwellung im Gesicht, Fieber, eine Fraktur nach einem Unfall oder ein ausgeschlagener Zahn sind Situationen, die nicht aufgeschoben werden dürfen. Besonders bei einem ausgeschlagenen bleibenden Zahn sind die ersten Minuten entscheidend. Ein Zahnunfall bei Kindern erfordert ein völlig anderes Vorgehen, je nachdem, ob ein Milchzahn oder ein bleibender Zahn betroffen ist.</p>
<h2>Die Grenze zwischen Behandlung und Vorbeugung</h2>
<p>Die meisten Eingriffe in der Zahnmedizin ersetzen verloren gegangenes Gewebe. Eine Füllung tritt an die Stelle kariösen Gewebes, eine Krone umfasst einen gebrochenen Zahn. Aber keine davon ist ein exakter Ersatz für natürliches Gewebe, und keine hält ewig. Der eigentliche Gewinn in der Zahnmedizin entsteht daher weniger aus der Qualität des Eingriffs als daraus, dass er gar nicht nötig wird.</p>
<p>Vorbeugung besteht aus konkreten Dingen: der richtigen Putztechnik, der Interdentalreinigung, einer Verringerung der Häufigkeit von Zuckerkonsum, der Nutzung von Fluorid und Kontrollen in Abständen, die zum persönlichen Risiko passen. Das klingt einfach, doch die Wirkung summiert sich.</p>
<h2>Warum ist das Vorgehen bei Kindern anders?</h2>
<p>Kinderzahnheilkunde ist keine verkleinerte Ausgabe der Erwachsenenbehandlung. Der Schmelz von Milchzähnen ist dünner, und Karies kann schneller voranschreiten. Ein früh verlorener Milchzahn kann den Platz verengen, der für den darunter liegenden bleibenden Zahn vorgesehen ist. Bei einem Unfall werden Milchzähne und bleibende Zähne völlig unterschiedlich behandelt; ein ausgeschlagener Milchzahn wird nicht wieder eingesetzt.</p>
<p>Darüber hinaus hängt der Erfolg der Behandlung bei einem Kind auch davon ab, welches Verhältnis es zu dem Ablauf entwickelt. Ein Kind, das in einer schmerzfreien Zeit zum ersten Mal kommt und die Praxis kennt, lässt sich später meist leichter behandeln. Der erste Besuch dient deshalb in der Regel nicht der Behandlung.</p>
<h2>Seiten in diesem Bereich</h2>
<h3>Karies, Füllung und Wurzelkanal</h3>
<ul>
<li><a href="/de/kanal-tedavisi/">Wurzelkanalbehandlung</a> — Wann sie durchgeführt wird, ihre Schritte und die anschließende Versorgung.</li>
<li><a href="/de/dis-curugu-kompozit-dolgu/">Karies und Kompositfüllungen</a> — Karies erkennen und die Behandlungsmöglichkeiten.</li>
</ul>
<h3>Erster Schritt und Kontrolle</h3>
<ul>
<li><a href="/de/ilk-dis-muayenesi-tedavi-planlamasi/">Erstuntersuchung und Behandlungsplanung</a> — Was bei einer Untersuchung beurteilt wird.</li>
<li>Regelmäßige Kontrollen — Was den Kontrollabstand bestimmt. <em>(in Vorbereitung)</em></li>
<li>Zahnarztangst — Das Vorgehen bei ängstlichen Patientinnen und Patienten. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Zahnfleisch</h3>
<ul>
<li>Professionelle Zahnreinigung und Zahnfleischgesundheit — Wie Zahnstein entsteht und was die Reinigung umfasst. <em>(in Vorbereitung)</em></li>
<li>Zahnfleischerkrankungen — Der Unterschied zwischen Gingivitis und Parodontitis. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Schmerzen, Empfindlichkeit und Notfälle</h3>
<ul>
<li>Zahnärztliche Notfälle — Wann man nicht warten sollte und was zuerst zu tun ist. <em>(in Vorbereitung)</em></li>
<li>Zahnempfindlichkeit — Ursachen für Empfindlichkeit gegenüber Kälte und Wärme. <em>(in Vorbereitung)</em></li>
</ul>
<h3>Kinder und besondere Lebensphasen</h3>
<ul>
<li><a href="/de/cocuk-dis-hekimligi/">Kinderzahnheilkunde</a> — Alter bei der Erstuntersuchung, Karies an Milchzähnen, Fluorid.</li>
<li><a href="/de/hamilelikte-dis-tedavisi/">Zahnbehandlung in der Schwangerschaft</a> — Planung nach Trimester und Pflege zu Hause.</li>
<li><a href="/de/cocuklarda-dis-travmasi/">Zahnunfälle bei Kindern</a> — Die ersten 30 Minuten nach einem Bruch oder Zahnverlust.</li>
</ul>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Wie oft sollte ich zur Kontrolle kommen?</strong><br>Es gibt kein einheitliches Intervall für alle. Kariesrisiko, Zustand des Zahnfleischs, Mundhygiene, Rauchverhalten und Allgemeinerkrankungen werden beurteilt, um einen auf Sie abgestimmten Abstand festzulegen.</p>
<p><strong>Ich habe keine Schmerzen — brauche ich trotzdem eine Untersuchung?</strong><br>Ja. Frühe Karies und der Beginn einer Zahnfleischerkrankung verlaufen meist schmerzfrei. Ein früh erkanntes Problem lässt sich mit einem kleineren Eingriff behandeln.</p>
<p><strong>Mein Zahnfleisch blutet beim Putzen; soll ich aufhören zu putzen?</strong><br>Nein. Bei den meisten plaquebedingten Zuständen verschlimmert ein Aussetzen der Reinigung die Entzündung. Reinigen Sie weiter sanft und regelmäßig mit einer weichen Bürste und vereinbaren Sie einen Kontrolltermin.</p>
<p><strong>Wann sollte ich mein Kind zum ersten Mal bringen?</strong><br>Innerhalb von sechs Monaten nach dem Durchbruch des ersten Milchzahns, spätestens zum ersten Geburtstag. Dieser Besuch dient meist nicht der Behandlung, sondern der Risikobeurteilung und dem Kennenlernen.</p>
<p><strong>Welche Zahnpasta soll ich verwenden?</strong><br>Die Wahl hängt von Alter, Kariesrisiko, Empfindlichkeit und dem Zustand des Zahnfleischs ab. Was für Sie geeignet ist, erläutern wir bei der Untersuchung.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt erfolgt die Beurteilung der Mund- und Zahngesundheit durch die gemeinsame Betrachtung Ihrer Beschwerden, der Befunde in der Mundhöhle und der erforderlichen Bildgebung; daraus ergeben sich eine individuelle Pflegeempfehlung und ein Kontrollintervall.</p>
<p><a href="/de/iletisim">Termin und Kontakt</a></p>',
'Karies, Zahnfleisch, Zahnschmerzen, Empfindlichkeit, tägliche Pflege und Kinderzahngesundheit: von der Untersuchung bis zur Vorbeugung.',
'Mund- und Zahngesundheit | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'agiz-dis-sagligi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Mund-, Kiefer- und Gesichtschirurgie',
'<p>Oralchirurgische Eingriffe erfordern, dass Zahn, Kieferknochen und die umgebenden Strukturen gemeinsam beurteilt werden. Die Lage eines Zahns, die Form seiner Wurzeln, sein Verhältnis zum Knochen und die benachbarten anatomischen Strukturen werden erst durch die klinische Untersuchung und geeignete Bildgebung erkennbar. Ein chirurgischer Eingriff wird daher nicht geplant, indem man in den Mund schaut und sagt, ein Zahn „müsse raus“.</p>
<p>Im Unterkiefer beeinflusst das Verhältnis zwischen den Wurzeln des Zahns und dem Unterkieferkanal die Planung unmittelbar, im Oberkiefer die Nähe der Zähne zur Kieferhöhle. Diese Verhältnisse werden in manchen Fällen mit einer Panoramaaufnahme, in anderen mit dreidimensionaler Bildgebung beurteilt.</p>
<h2>Nicht jeder verlagerte Zahn wird entfernt</h2>
<p>Wenn Weisheitszähne im Mund keinen Platz finden, brechen sie unter Umständen nur teilweise durch oder bleiben im Knochen verlagert. Das erfordert nicht immer eine Entfernung. Eine Entfernung wird in Situationen wie Schmerzen, wiederkehrender Entzündung, Schädigung des Nachbarzahns, Verdacht auf eine Zyste, einer nicht zu reinigenden Lage oder aufgrund einer anderen geplanten Behandlung erwogen. Bei Zähnen, die keine Beschwerden verursachen und beobachtet werden können, kann eine Kontrolle vorgezogen werden.</p>
<p>Dasselbe gilt für die chirurgische Entfernung: Zuerst wird beurteilt, ob der Zahn erhalten werden kann. Wo sich der Zahn durch eine Wurzelkanalbehandlung, eine Wurzelspitzenresektion oder eine restaurative Lösung im Mund halten lässt, ist die Entfernung nicht die erste Wahl.</p>
<h2>Risiken werden von Anfang an erläutert</h2>
<p>Schwellung, Druckempfindlichkeit, eine eingeschränkte Mundöffnung und Schwierigkeiten beim Kauen sind nach chirurgischen Eingriffen zu erwartende Befunde. Sie sind keine Komplikationen, sondern ein gewöhnlicher Teil der Heilung und meist in den ersten Tagen am deutlichsten. Darüber hinaus hat jeder Eingriff eigene Risiken; dazu zählen Risiken durch die anatomische Nachbarschaft, Blutung, Infektion und eine langsamer als erwartet verlaufende Heilung.</p>
<p>Diese Risiken individuell zu erläutern, gehört zum Eingriff. Welche Befunde zu erwarten sind und welche ein sofortiges Vorstellen erfordern, wird vor und nach dem Eingriff besprochen.</p>
<h2>Das Knochenangebot gehört zur Implantatplanung</h2>
<p>Ein wesentlicher Teil der Oralchirurgie ist mit der Implantatbehandlung verbunden. Ist ein Zahn vor längerer Zeit verloren gegangen, kann das Knochenangebot in diesem Bereich abgenommen haben. In solchen Fällen kann vor dem Implantat ein Knochenaufbau oder im hinteren Oberkiefer eine Anhebung des Kieferhöhlenbodens in Betracht kommen. Das ist nicht bei jeder Patientin und jedem Patienten nötig; der Bedarf ergibt sich aus der gemeinsamen Beurteilung von Bildgebung und prothetischem Plan.</p>
<h2>Der Planungsprozess wird offen erläutert</h2>
<p>Umfang und Bedingungen jedes chirurgischen Eingriffs sind unterschiedlich. Nach der Beurteilung legen wir fest, unter welchen Bedingungen und mit welchem Team der Eingriff durchgeführt werden sollte; diese Planung wird der Patientin oder dem Patienten offen erläutert und der Ablauf gemeinsam festgelegt.</p>
<p>Nach seinem Studium an der Zahnmedizinischen Fakultät der Universität Istanbul schloss MSc. Dt. Mehmet Taş in Italien ein Masterstudium in Oralchirurgie und Implantologie ab. Dieser Abschluss ist kein Facharzttitel; er bildet die wissenschaftliche Grundlage des Vorgehens bei chirurgischer und implantologischer Planung.</p>
<h2>Vorbereitung vor dem Eingriff</h2>
<p>Vor einem chirurgischen Eingriff gibt es Angaben, die mitgeteilt werden müssen: bekannte Erkrankungen, regelmäßig eingenommene Medikamente, Allergien, frühere Operationen und jede Erkrankung im Zusammenhang mit der Blutgerinnung. Gerinnungshemmende Medikamente, Arzneimittel mit Einfluss auf den Knochenstoffwechsel und immunsuppressive Therapien wirken sich unmittelbar auf die Planung aus.</p>
<p>Diese Medikamente dürfen nicht ohne ärztlichen Rat abgesetzt werden. Bei Bedarf stimmen wir uns mit der behandelnden Ärztin oder dem behandelnden Arzt ab und legen Zeitpunkt und Vorgehen entsprechend fest.</p>
<h2>Was ist während der Heilung zu erwarten?</h2>
<p>Die ersten Tage der Heilung verlaufen anders als die folgenden Wochen. Die ersten 24 Stunden sind für den Schutz des Blutgerinnsels wichtig: Vermeiden Sie es, den Bereich zu belasten, spülen Sie nicht kräftig, trinken Sie nicht mit einem Strohhalm und verzichten Sie auf das Rauchen. Eine Schwellung nimmt in den ersten Tagen meist zu und geht danach zurück. Die Mundöffnung kann vorübergehend eingeschränkt sein.</p>
<p>Das sind zu erwartende Befunde. Dagegen erfordern zunehmende und nicht abklingende Schmerzen, hohes Fieber, ausgedehnte Schwellung, übler Geruch oder Austritt von Sekret sowie Schluck- oder Atembeschwerden eine unverzügliche Vorstellung.</p>
<h2>Seiten in diesem Bereich</h2>
<ul>
<li><a href="/de/agiz-cerrahisi-uygulamalari/">Oralchirurgische Eingriffe</a> — Umfang, Beurteilung vor dem Eingriff, Heilung und Aufklärung über Risiken.</li>
<li>Verlagerte Weisheitszähne — Wann eine Entfernung erwogen und wann beobachtet wird. <em>(in Vorbereitung)</em></li>
<li>Knochentransplantat und Knochenaufbau — Verfahren und Heilung bei unzureichendem Knochen. <em>(in Vorbereitung)</em></li>
<li>Sinuslift — Das Vorgehen bei geringer Knochenhöhe im hinteren Oberkiefer. <em>(in Vorbereitung)</em></li>
</ul>
<h2>Häufig gestellte Fragen</h2>
<p><strong>Mein Weisheitszahn tut nicht weh — sollte er trotzdem entfernt werden?</strong><br>Ohne Beschwerden ist eine Entfernung nicht automatisch erforderlich. Die Lage des Zahns, seine Reinigungsfähigkeit, seine Wirkung auf den Nachbarzahn und die Röntgenbefunde werden beurteilt, um zu entscheiden, ob Entfernung oder Beobachtung angebracht ist.</p>
<p><strong>Spürt man während des Eingriffs Schmerzen?</strong><br>Der Eingriff erfolgt unter Lokalanästhesie, angestrebt wird ein angenehmer Ablauf. Druck und Vibration können wahrgenommen werden. Da das Erleben individuell unterschiedlich ist, wird keine vollständige Schmerzfreiheit zugesichert.</p>
<p><strong>Wie lange hält die Schwellung an?</strong><br>Eine Schwellung ist meist in den ersten Tagen am deutlichsten und geht dann zurück. Die Dauer hängt vom Umfang des Eingriffs und von der Person ab. Bei zunehmenden Schmerzen, Fieber oder ausgedehnter Schwellung sollten Sie sich ohne Abwarten vorstellen.</p>
<p><strong>Ich nehme Gerinnungshemmer — ist der Eingriff möglich?</strong><br>Bitte teilen Sie uns Ihre Medikamente mit. Gerinnungshemmer dürfen nicht ohne ärztlichen Rat abgesetzt werden; bei Bedarf planen wir gemeinsam mit der behandelnden Ärztin oder dem behandelnden Arzt.</p>
<p><strong>Ist bei jedem Implantat ein Knochentransplantat nötig?</strong><br>Nein. Der Bedarf ergibt sich aus der gemeinsamen Beurteilung des vorhandenen Knochenangebots und des geplanten Zahnersatzes; in den meisten Fällen ist kein zusätzlicher Eingriff erforderlich.</p>
<p><strong>Kann ich nach dem Eingriff zur Arbeit oder zur Schule?</strong><br>Das hängt vom Umfang des Eingriffs ab. Für den ersten Tag kann Schonung empfohlen werden. Hinweise speziell für Sie erhalten Sie vorab.</p>
<h2>Regionale Beurteilung</h2>
<p>In unserer Praxis an der Verbindung Beylikdüzü–Esenyurt wird der Bedarf an chirurgischen Maßnahmen durch die gemeinsame Beurteilung von klinischer Untersuchung, erforderlicher Bildgebung und den anatomischen Nachbarschaften bestimmt. Im Anschluss wird der geeignete Behandlungsplan gemeinsam mit der Patientin oder dem Patienten festgelegt.</p>
<p><a href="/de/dental-implant-tedavisi/">Zahnimplantat-Behandlung</a> &middot; <a href="/de/kanal-tedavisi/">Wurzelkanalbehandlung</a> &middot; <a href="/de/iletisim">Termin und Kontakt</a></p>',
'Verlagerte Weisheitszähne, chirurgische Zahnentfernung, Knochenaufbau und Sinuslift: Beurteilung, Planung und Heilungsverlauf.',
'Mund-, Kiefer- und Gesichtschirurgie | MSc. Dt. Mehmet Taş',
'DE' FROM pages WHERE link = 'cerrahi';

